import { NullValueException, UndefinedValueException } from './exceptions';

/* Required for typescript 2.4 as it's missing from lib.es5.d.ts in this version */
declare function escape(s: string): string;

/**
 * Parse a string or UTF-8 string
 *
 * @export
 * @param {(string | null | undefined)} value
 * @param {string} [propertyName]
 * @returns {string}
 * @throws {NullValueException}
 * @throws {UndefinedValueException}
 * @throws {StringDecoderException} if a UTF-8 string cannot be decoded
 */
export function parseString(value: string | null | undefined, propertyName?: string): string {
    if (value === null) {
        throw new NullValueException('string', propertyName);
    }

    if (value === void 0) {
        throw new UndefinedValueException('string', propertyName);
    }

    let parsedValue = value;
    try {
        parsedValue = decodeURIComponent(escape(value));
    } catch (err) {
        // This will fail if its malformed, so just return the original
    }
    return parsedValue;
}
